<?php declare(strict_types=1); $base=config('app.base_path'); ?><div class="page-header"><div><h1><?= $trash?'Deleted Experiences':'Tourism Experiences' ?></h1><p>Things visitors can do, not just places they can visit.</p></div><div class="page-actions"><?php if($trash): ?><a class="btn btn-secondary" href="<?=$base?>/tourism/experiences">Active</a><?php else: ?><a class="btn btn-secondary" href="<?=$base?>/tourism/experiences?view=trash">Trash</a><a class="btn btn-primary" href="<?=$base?>/tourism/experiences/create">Add Experience</a><?php endif; ?></div></div><div class="card table-responsive"><table class="table"><thead><tr><th>Experience</th><th>Destination</th><th>Duration</th><th>Price</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($experiences as $e): ?><tr><td><strong><?=htmlspecialchars($e['title'])?></strong></td><td><?=htmlspecialchars((string)($e['destination_name']??'—'))?></td><td><?= $e['duration_minutes']?(int)$e['duration_minutes'].' min':'—' ?></td><td><?= $e['price']!==null?'₹'.number_format((float)$e['price'],2):'—' ?></td><td><?=htmlspecialchars($e['status'])?></td><td><?php if($trash): ?><form method="post" action="<?=$base?>/tourism/experiences/<?=$e['id']?>/restore"><button class="btn btn-secondary">Restore</button></form><?php else: ?><a class="link-button" href="<?=$base?>/tourism/experiences/<?=$e['id']?>">View</a> <a class="link-button" href="<?=$base?>/tourism/experiences/<?=$e['id']?>/edit">Edit</a><?php endif; ?></td></tr><?php endforeach; if(!$experiences): ?><tr><td colspan="6">No experiences found.</td></tr><?php endif; ?></tbody></table></div>
